/* @autogenerated */
package net.civeira.phylax.feature.observe.access;

/**
 * Access level to the observability viewer and its api. Each level includes the previous ones.
 */
public enum ObserveLevel {
  /** See logs, traces and origins (without their ingest keys). */
  READ,
  /** READ, plus change the state of what is shown (annotations, dashboards). */
  WRITE,
  /** WRITE, plus manage the origins, their ingest keys and the stored data. */
  ADMIN;

  /**
   * @return true if this level grants {@code required}
   */
  public boolean includes(final ObserveLevel required) {
    return ordinal() >= required.ordinal();
  }
}
